import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"方案介绍","description":"","frontmatter":{},"headers":[],"relativePath":"nex2DevelopmentCases_detailPage_dynamicControl_toggleTopRightActionButtonByComplexLogic_solutionOverview.md","filePath":"nex2DevelopmentCases_detailPage_dynamicControl_toggleTopRightActionButtonByComplexLogic_solutionOverview.md"}'),l={name:"nex2DevelopmentCases_detailPage_dynamicControl_toggleTopRightActionButtonByComplexLogic_solutionOverview.md"};function r(d,t,n,h,s,p){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="方案介绍" tabindex="-1">方案介绍 <a class="header-anchor" href="#方案介绍" aria-label="Permalink to &quot;方案介绍&quot;">​</a></h1><h2 id="方案概述" tabindex="-1">方案概述 <a class="header-anchor" href="#方案概述" aria-label="Permalink to &quot;方案概述&quot;">​</a></h2><p>本方案通过在详情页（EntityDetail）中进行组件级扩展实现。通过扩展详情页的操作按钮逻辑，在页面加载时获取当前用户的职能信息职能及合同负责人字段，并根据预设条件动态控制右上角操作按钮（“编辑”、“删除”）的显示与隐藏。该方案可实现基于字段与用户属性的多维度权限控制，确保操作权限与业务规则一致，提升系统的安全性与使用体验。</p><h2 id="扩展组件" tabindex="-1">扩展组件 <a class="header-anchor" href="#扩展组件" aria-label="Permalink to &quot;扩展组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终端</th><th>扩展对象</th><th>扩展页面</th><th>扩展区域</th><th>扩展组件</th><th>扩展功能</th></tr></thead><tbody><tr><td>网页端/移动端</td><td>签约合同</td><td>详情页</td><td>页面头部</td><td>头部按钮</td><td>在页面渲染后，根据用户职能和数据属性进行判断，动态控制“编辑”和“删除”按钮的显示</td></tr></tbody></table><h2 id="功能设计" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计" aria-label="Permalink to &quot;功能设计&quot;">​</a></h2><ol><li><p><strong>触发时机</strong></p><p>当详情页渲染完成后，执行权限判定逻辑。</p></li><li><p><strong>数据获取</strong></p><ul><li>获取当前登录用户的职能信息（主要职能）。</li><li>获取当前合同记录的关键字段值（负责人、合同金额、合同状态）。</li></ul></li><li><p><strong>逻辑判定</strong></p><ul><li><p><strong>编辑按钮控制</strong></p><p>仅当当前登录用户为合同负责人，且合同状态为“草稿”，并且合同金额 ≤ 500 万元时，显示“编辑”按钮。否则，隐藏“编辑”按钮。</p></li><li><p><strong>删除按钮控制</strong></p><p>仅当当前登录用户的主要职能为“默认管理员”时，显示“删除”按钮。否则，隐藏“删除”按钮。</p></li></ul></li></ol><h2 id="使用的-nex-扩展能力" tabindex="-1">使用的 NEX 扩展能力 <a class="header-anchor" href="#使用的-nex-扩展能力" aria-label="Permalink to &quot;使用的 NEX 扩展能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能点</th><th>扩展能力类别</th><th>属性/函数/事件</th><th>说明</th><th>示例值/使用方式</th></tr></thead><tbody><tr><td>页面渲染后执行操作按钮逻辑</td><td>事件绑定</td><td>事件：afterRender</td><td>定义页面渲染完成后执行的逻辑，用于根据用户角色和数据属性动态控制“编辑”和“删除”按钮的显示</td><td>afterRender: (e) =&gt; { ... }</td></tr><tr><td>控制按钮的显示/隐藏</td><td>界面控制</td><td>属性：visible</td><td>控制编辑和删除按钮的显示/隐藏</td><td>visible: true</td></tr></tbody></table><h2 id="使用的其他能力" tabindex="-1">使用的其他能力 <a class="header-anchor" href="#使用的其他能力" aria-label="Permalink to &quot;使用的其他能力&quot;">​</a></h2><p>无</p>',11)])])}const g=e(l,[["render",r]]);export{_ as __pageData,g as default};
